program.compute:
options = read('/input/options')
ids = []
for option in options:
    ids = ids + [option['id']]
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(ids, size):
        candidate = list(group)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
if receipt('report') == 'unattempted':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

